PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL,email_normalized TEXT NOT NULL UNIQUE,email_verified_at TEXT,status TEXT NOT NULL DEFAULT 'pending_verification' CHECK(status IN ('pending_verification','active','suspended','deleted')),role TEXT,display_name TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,last_login_at TEXT,deleted_at TEXT);
CREATE INDEX IF NOT EXISTS users_status_created_idx ON users(status,created_at);
CREATE TABLE IF NOT EXISTS credentials(id TEXT PRIMARY KEY,user_id TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,password_changed_at TEXT NOT NULL,password_version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,token_hash BLOB NOT NULL UNIQUE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,last_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,last_renewed_at TEXT,idle_expires_at TEXT NOT NULL,absolute_expires_at TEXT NOT NULL,revoked_at TEXT,ip_prefix TEXT,user_agent_hash BLOB,password_version INTEGER NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS sessions_user_expiry_idx ON sessions(user_id,revoked_at,idle_expires_at,absolute_expires_at);
CREATE INDEX IF NOT EXISTS sessions_user_seen_idx ON sessions(user_id,last_seen_at DESC);
CREATE TABLE IF NOT EXISTS email_verification_tokens(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,token_hash BLOB NOT NULL UNIQUE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at TEXT NOT NULL,consumed_at TEXT,request_ip_prefix TEXT,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS email_tokens_expiry_idx ON email_verification_tokens(expires_at);
CREATE INDEX IF NOT EXISTS email_tokens_user_created_idx ON email_verification_tokens(user_id,created_at);
CREATE TABLE IF NOT EXISTS password_reset_tokens(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,token_hash BLOB NOT NULL UNIQUE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at TEXT NOT NULL,consumed_at TEXT,request_ip_prefix TEXT,credential_password_version INTEGER NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS password_tokens_expiry_idx ON password_reset_tokens(expires_at);
CREATE INDEX IF NOT EXISTS password_tokens_user_created_idx ON password_reset_tokens(user_id,created_at);
CREATE TABLE IF NOT EXISTS oauth_accounts(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,provider TEXT NOT NULL,provider_user_id TEXT NOT NULL,provider_login TEXT,provider_email TEXT,provider_email_normalized TEXT,provider_email_verified INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,last_used_at TEXT,UNIQUE(provider,provider_user_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS oauth_accounts_user_idx ON oauth_accounts(user_id);
CREATE TABLE IF NOT EXISTS oauth_states(id TEXT PRIMARY KEY,state_hash BLOB NOT NULL UNIQUE,cookie_binding_hash BLOB NOT NULL,purpose TEXT NOT NULL CHECK(purpose IN ('login','link')),user_id TEXT,session_binding_hash BLOB,pkce_verifier_encrypted BLOB NOT NULL,redirect_key TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at TEXT NOT NULL,consumed_at TEXT,request_ip_prefix TEXT,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS oauth_states_expiry_idx ON oauth_states(expires_at);
CREATE INDEX IF NOT EXISTS oauth_states_user_created_idx ON oauth_states(user_id,created_at);
CREATE TABLE IF NOT EXISTS roles(id TEXT PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,is_system INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS permissions(id TEXT PRIMARY KEY,code TEXT NOT NULL UNIQUE,description TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS role_permissions(role_id TEXT NOT NULL,permission_id TEXT NOT NULL,PRIMARY KEY(role_id,permission_id),FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE,FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS role_permissions_permission_idx ON role_permissions(permission_id);
CREATE TABLE IF NOT EXISTS user_roles(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,role_id TEXT NOT NULL,granted_by_user_id TEXT,granted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,revoked_at TEXT,reason TEXT,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(granted_by_user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE RESTRICT);
CREATE INDEX IF NOT EXISTS user_roles_user_revoked_idx ON user_roles(user_id,revoked_at);
CREATE INDEX IF NOT EXISTS user_roles_role_idx ON user_roles(role_id);
CREATE TABLE IF NOT EXISTS audit_shards(id TEXT PRIMARY KEY,shard_key TEXT NOT NULL UNIQUE,chain_id TEXT NOT NULL UNIQUE,kind TEXT NOT NULL CHECK(kind IN ('primary','compensation')),state TEXT NOT NULL DEFAULT 'open' CHECK(state IN ('open','closing','sealed')),hour_started_at TEXT,received_at TEXT,source_shard_id TEXT,source_manifest_hash BLOB,previous_manifest_hash BLOB,genesis_anchor_hash BLOB NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,sealed_at TEXT,FOREIGN KEY(source_shard_id) REFERENCES audit_shards(id) ON DELETE RESTRICT);
CREATE INDEX IF NOT EXISTS audit_shards_kind_state_created_idx ON audit_shards(kind,state,created_at);
CREATE INDEX IF NOT EXISTS audit_shards_source_idx ON audit_shards(source_shard_id);
CREATE TABLE IF NOT EXISTS audit_manifests(id TEXT PRIMARY KEY,shard_id TEXT NOT NULL UNIQUE,manifest_hash BLOB NOT NULL UNIQUE,previous_manifest_hash BLOB,source_manifest_hash BLOB,genesis_anchor_hash BLOB NOT NULL,first_sequence_no INTEGER,last_sequence_no INTEGER,row_count INTEGER NOT NULL,first_entry_hash BLOB,last_entry_hash BLOB,signature BLOB NOT NULL,signature_key_id TEXT NOT NULL,signature_algorithm TEXT NOT NULL,canonicalization_version TEXT NOT NULL,sealed_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(shard_id) REFERENCES audit_shards(id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS audit_logs(id TEXT PRIMARY KEY,shard_id TEXT NOT NULL,shard_kind TEXT NOT NULL CHECK(shard_kind IN ('primary','compensation')),chain_id TEXT NOT NULL,sequence_no INTEGER NOT NULL,occurred_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,source_occurred_at TEXT,source_shard_id TEXT,source_manifest_hash BLOB,prev_hash BLOB NOT NULL,entry_hash BLOB NOT NULL,manifest_anchor_hash BLOB NOT NULL,compensation_manifest_prev_hash BLOB,actor_user_id TEXT,target_user_id TEXT,actor_ref TEXT NOT NULL,actor_type TEXT NOT NULL,action TEXT NOT NULL,outcome TEXT NOT NULL CHECK(outcome IN ('success','failure','blocked')),request_id TEXT,ip_prefix TEXT,user_agent_hash BLOB,metadata TEXT NOT NULL DEFAULT '{}',UNIQUE(chain_id,sequence_no),FOREIGN KEY(actor_user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(target_user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(shard_id) REFERENCES audit_shards(id) ON DELETE RESTRICT,FOREIGN KEY(source_shard_id) REFERENCES audit_shards(id) ON DELETE RESTRICT);
CREATE INDEX IF NOT EXISTS audit_logs_occurred_idx ON audit_logs(occurred_at);
CREATE INDEX IF NOT EXISTS audit_logs_actor_occurred_idx ON audit_logs(actor_user_id,occurred_at);
CREATE INDEX IF NOT EXISTS audit_logs_action_occurred_idx ON audit_logs(action,occurred_at);
CREATE INDEX IF NOT EXISTS audit_logs_shard_sequence_idx ON audit_logs(shard_id,sequence_no);
CREATE INDEX IF NOT EXISTS audit_logs_source_shard_idx ON audit_logs(source_shard_id);
CREATE TABLE IF NOT EXISTS quota_ledger(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,delta INTEGER NOT NULL,source_type TEXT NOT NULL,idempotency_key TEXT NOT NULL UNIQUE,related_user_id TEXT,reason TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT);
CREATE INDEX IF NOT EXISTS quota_ledger_user_created_idx ON quota_ledger(user_id,created_at);
CREATE TABLE IF NOT EXISTS rate_limit_buckets(id TEXT PRIMARY KEY,dimension TEXT NOT NULL,subject_hash TEXT NOT NULL,window_start TEXT NOT NULL,count INTEGER NOT NULL DEFAULT 0,expires_at TEXT NOT NULL,UNIQUE(dimension,subject_hash,window_start));
CREATE INDEX IF NOT EXISTS rate_limit_buckets_expiry_idx ON rate_limit_buckets(expires_at);
CREATE TABLE IF NOT EXISTS domain_inventory(id TEXT PRIMARY KEY,zone_id TEXT NOT NULL UNIQUE,domain TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'available' CHECK(status IN ('available','claimed','disabled')),source TEXT NOT NULL DEFAULT 'dnshe',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS domain_inventory_status_domain_idx ON domain_inventory(status,domain);
CREATE TABLE IF NOT EXISTS user_domains(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,inventory_id TEXT NOT NULL UNIQUE,domain TEXT NOT NULL,dnshe_zone_id TEXT NOT NULL,claimed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','released')),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(inventory_id) REFERENCES domain_inventory(id) ON DELETE RESTRICT);
CREATE INDEX IF NOT EXISTS user_domains_user_claimed_idx ON user_domains(user_id,claimed_at DESC);
CREATE INDEX IF NOT EXISTS user_domains_zone_idx ON user_domains(dnshe_zone_id);
